package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import net.minecraft.core.*;import org.joml.Vector3d;
public class DefenseGeometryTest{
 @Test public void everyHelperResolvesToOneRootInAllFourDirections(){var root=new BlockPos(731,74,-142);for(var model:DefenseGeometry.MODELS){assertTrue(model.cells.length<256);for(var f:Direction.Plane.HORIZONTAL)for(int i=0;i<model.cells.length;i++)assertEquals(root,model.root(model.cell(root,f,model.cells[i]),f,i));assertTrue(model.bounds.maxY>6&&model.bounds.maxY<10);}}
 @Test public void readyUsesTheAuthoredDeployedPoseRatherThanAddingAnotherElevation(){var model=DefenseGeometry.MODELS[0];for(var f:Direction.Plane.HORIZONTAL)for(int i=0;i<4;i++){var ready=model.launchDirection(BlockPos.ZERO,f,i,0);var service=model.launchDirection(BlockPos.ZERO,f,i,1);assertEquals(Math.sin(Math.toRadians(62)),ready.y,1e-6);assertEquals(Math.sin(Math.toRadians(35)),service.y,1e-6);assertEquals(1,ready.length(),1e-8);assertTrue(ready.x*f.getStepX()+ready.z*f.getStepZ()>.46);}assertTrue(model.exit(BlockPos.ZERO,Direction.SOUTH,2,0).y>model.exit(BlockPos.ZERO,Direction.SOUTH,0,0).y);}
 @Test public void openingOneCoverDoesNotMoveTheOtherThreeOrTheStaticChassis(){var model=DefenseGeometry.MODELS[0];var a=model.transforms(0,-1,new float[4]);var b=model.transforms(0,-1,new float[]{0,1,0,0});for(int i=0;i<model.bones.size();i++){String name=model.bones.get(i).name();if(name.equals("Muzzle_Cover_02"))assertFalse(a[i].equals(b[i],1e-8));else assertTrue(a[i].equals(b[i],1e-8),name);}}
 @Test public void scanLoopsAndThePanelAndRamsKeepTheirAuthoredHierarchy(){var model=DefenseGeometry.MODELS[1];var a=model.transforms(0,0,new float[4]);var b=model.transforms(0,10,new float[4]);var scan=model.transforms(0,2.5,new float[4]);for(int i=0;i<a.length;i++){assertTrue(a[i].equals(b[i],1e-8));var bone=model.bones.get(i);if(bone.name().equals("Radar_Azimuth"))assertFalse(a[i].equals(scan[i],1e-8));if(bone.name().equals("Operator_Console"))assertTrue(a[i].equals(scan[i],1e-8));if(bone.name().equals("Panel_Ram_L_Rod"))assertEquals("Panel_Ram_L",model.bones.get(bone.parent()).name());}assertEquals(-30,model.sample("dr01.lower_to_service","Radar_Panel_Tilt","rotation",3).x,1e-8);}
}
